package com.novacommerce.order.application; import com.novacommerce.order.config.OrderProperties; import com.novacommerce.order.domain.order.*; import com.novacommerce.order.infrastructure.persistence.*; import java.time.*; import org.springframework.data.domain.PageRequest; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class OrderReconciliation{private final OrderRepository orders;private final CartRepository carts;private final OrderProperties props;private final Clock clock;public OrderReconciliation(OrderRepository o,CartRepository c,OrderProperties p,Clock k){orders=o;carts=c;props=p;clock=k;}@Scheduled(fixedDelayString="${order.reconciliation-interval:PT30S}")@Transactional public void reconcile(){Instant now=clock.instant();for(CustomerOrder o:orders.findExpirable(now.minus(props.getPendingCheckoutTimeout()),now,PageRequest.of(0,100))){o.expire(now);carts.findById(o.getSourceCartId()).ifPresent(c->c.reopen(now));}}}
